378	// 构造在某个属性值里填充 n 个 ASCII 字符的商品 JSON；每多一个字符请求体恰好多一个字节。
379	function paddedProductJson(pad: number, price = '1.00'): Buffer {
380	  return Buffer.from(JSON.stringify({
381	    name: '边界商品',
382	    specs: [{ attributes: [{ name: '颜色', value: 'a'.repeat(pad) }], price, stock: 1 }],
383	  }), 'utf8');
384	}
385	
386	// 找到请求体字节数不超过上限的最大填充长度（ASCII 填充时可恰好凑到上限）。
387	function maxPadWithinLimit(price = '1.00'): number {
388	  let lo = 0;
389	  let hi = MAX_BODY_BYTES;
390	  while (lo < hi) {
391	    const mid = Math.floor((lo + hi + 1) / 2);
392	    if (paddedProductJson(mid, price).length <= MAX_BODY_BYTES) lo = mid;
393	    else hi = mid - 1;
394	  }
395	  return lo;
396	}
