795	const CHROME_BIN = findChrome();
796	const CHROME_FLAGS = [
797	  '--headless=new',
798	  '--disable-gpu',
799	  '--no-sandbox',
800	  '--disable-dev-shm-usage',
801	  '--no-first-run',
802	  '--no-default-browser-check',
803	  '--disable-background-networking',
804	  '--disable-crash-reporter',
805	];
