807	class CdpBrowser {
808	  private child: ChildProcess;
809	  private profileDir: string;
810	  private ws: WebSocket;
811	  private nextId = 1;
812	  private pending = new Map<number, { resolve: (v: any) => void; reject: (e: Error) => void; sessionId?: string }>();
813	  private listeners = new Map<string, (method: string, params: any) => void>();
814	
815	  private constructor(child: ChildProcess, profileDir: string, ws: WebSocket) {
816	    this.child = child;
817	    this.profileDir = profileDir;
818	    this.ws = ws;
819	  }
820	
821	  static async launch(): Promise<CdpBrowser> {
822	    const profileDir = mkdtempSync(join(tmpdir(), 'cartwell-chrome-'));
823	    const child = spawn(
824	      CHROME_BIN!,
825	      [...CHROME_FLAGS, '--remote-debugging-port=0', `--user-data-dir=${profileDir}`, 'about:blank'],
826	      { stdio: ['ignore', 'ignore', 'pipe'] },
827	    );
828	    let stderr = '';
829	    child.stderr!.setEncoding('utf8');
830	    child.stderr.on('data', (chunk: string) => { stderr += chunk; });
831	
832	    const portFile = join(profileDir, 'DevToolsActivePort');
833	    const port = await new Promise<string>((resolve, reject) => {
834	      const started = Date.now();
835	      const timer = setInterval(() => {
836	        try {
837	          const line = readFileSync(portFile, 'utf8').split('\n')[0]!.trim();
838	          if (line) { clearInterval(timer); resolve(line); }
839	        } catch {
840	          if (Date.now() - started > 15_000) {
841	            clearInterval(timer);
842	            reject(new Error(`等待 Chrome 调试端口超时：${stderr.slice(-500)}`));
843	          }
844	        }
845	      }, 50);
846	    });
847	
848	    const version = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json();
849	    const ws = new WebSocket(version.webSocketDebuggerUrl as string);
850	    await new Promise<void>((resolve, reject) => {
851	      ws.onopen = (): void => resolve();
852	      ws.onerror = (): void => reject(new Error('无法连接 Chrome DevTools Protocol'));
853	    });
854	
855	    const browser = new CdpBrowser(child, profileDir, ws);
856	    ws.onmessage = (event: { data: string }): void => {
857	      const message: CdpMessage = JSON.parse(event.data);
858	      if (message.id !== undefined) {
859	        const entry = browser.pending.get(message.id);
860	        if (entry && (entry.sessionId === undefined || entry.sessionId === message.sessionId)) {
861	          browser.pending.delete(message.id);
862	          if (message.error) entry.reject(new Error(JSON.stringify(message.error)));
863	          else entry.resolve(message.result);
864	        }
865	        return;
866	      }
867	      if (message.method && message.sessionId) {
868	        browser.listeners.get(message.sessionId)?.(message.method, message.params);
869	      }
870	    };
871	    return browser;
872	  }
873	
874	  send(method: string, params: Record<string, unknown> = {}, sessionId?: string): Promise<any> {
875	    const id = this.nextId++;
876	    return new Promise((resolve, reject) => {
877	      this.pending.set(id, { resolve, reject, sessionId });
878	      this.ws.send(JSON.stringify({ id, method, params, ...(sessionId ? { sessionId } : {}) }));
879	    });
880	  }
881	
882	  async newPage(url: string): Promise<CdpPage> {
883	    const { targetId } = await this.send('Target.createTarget', { url: 'about:blank' });
884	    const { sessionId } = await this.send('Target.attachToTarget', { targetId, flatten: true });
885	    const page = new CdpPage(this, sessionId);
886	    this.listeners.set(sessionId, (method, params): void => {
887	      if (method === 'Fetch.requestPaused') page.handlePaused(params);
888	    });
889	    await this.send('Page.enable', {}, sessionId);
890	    await this.send('Runtime.enable', {}, sessionId);
891	    // 只拦截新增商品请求：在请求真正发出后暂停，便于核对载荷与提交过程中的按钮状态。
892	    await this.send('Fetch.enable', {
893	      patterns: [{ urlPattern: '*/api/products', requestStage: 'Request' }],
894	    }, sessionId);
895	    await this.send('Page.navigate', { url }, sessionId);
896	    await page.waitFor("document.getElementById('product-form') && document.querySelectorAll('#specs [data-spec]').length === 1");
897	    return page;
898	  }
899	
900	  async close(): Promise<void> {
901	    try { this.ws.close(); } catch { /* 已关闭 */ }
902	    this.child.kill('SIGTERM');
903	    await Promise.race([
904	      once(this.child, 'exit'),
905	      new Promise((resolve) => setTimeout(resolve, 3000)),
906	    ]);
907	    if (this.child.exitCode === null) this.child.kill('SIGKILL');
908	    rmSync(this.profileDir, { recursive: true, force: true });
909	  }
910	}
