912	class CdpPage {
913	  private browser: CdpBrowser;
914	  private sessionId: string;
915	  private readonly pausedQueue: any[] = [];
916	  private readonly pausedWaiters: Array<(params: any) => void> = [];
917	
918	  constructor(browser: CdpBrowser, sessionId: string) {
919	    this.browser = browser;
920	    this.sessionId = sessionId;
921	  }
922	
923	  handlePaused(params: any): void {
924	    const waiter = this.pausedWaiters.shift();
925	    if (waiter) waiter(params);
926	    else this.pausedQueue.push(params);
927	  }
928	
929	  send(method: string, params: Record<string, unknown> = {}): Promise<any> {
930	    return this.browser.send(method, params, this.sessionId);
931	  }
932	
933	  async eval(expression: string): Promise<any> {
934	    const result = await this.send('Runtime.evaluate', {
935	      expression,
936	      returnByValue: true,
937	      awaitPromise: true,
938	    });
939	    if (result.exceptionDetails) {
940	      throw new Error(`页面脚本执行失败：${result.exceptionDetails.text} ${result.exceptionDetails.exception?.description ?? ''}`);
941	    }
942	    return result.result.value;
943	  }
944	
945	  // 轮询页面上的布尔条件；提交成功后的整页跳转也会经历短暂的上下文切换，忽略期间的异常。
946	  async waitFor(expression: string, timeoutMs = 8000, label?: string): Promise<void> {
947	    const deadline = Date.now() + timeoutMs;
948	    for (;;) {
949	      try {
950	        if (await this.eval(expression)) return;
951	      } catch {
952	        if (Date.now() > deadline) throw new Error(`等待页面条件超时：${label ?? expression}`);
953	      }
954	      if (Date.now() > deadline) throw new Error(`等待页面条件超时：${label ?? expression}`);
955	      await new Promise((resolve) => setTimeout(resolve, 50));
956	    }
957	  }
958	
959	  async waitPaused(timeoutMs = 8000): Promise<any> {
960	    const queued = this.pausedQueue.shift();
961	    if (queued) return queued;
962	    return new Promise((resolve, reject) => {
963	      const timer = setTimeout(() => {
964	        const index = this.pausedWaiters.indexOf(resolve as any);
965	        if (index >= 0) this.pausedWaiters.splice(index, 1);
966	        reject(new Error('等待新增商品请求被拦截超时'));
967	      }, timeoutMs);
968	      this.pausedWaiters.push((params): void => { clearTimeout(timer); resolve(params); });
969	    });
970	  }
971	
972	  continueRequest(requestId: string): Promise<any> {
973	    return this.send('Fetch.continueRequest', { requestId });
974	  }
975	}
